const tabId = 103795365;
const allTrailers = await browserjs(tabId, () => {
  const links = Array.from(document.querySelectorAll('a[href*="/view/d/"]'));
  const seen = new Set();
  const res = [];
  for (const l of links) {
    const text = l.querySelector('.label')?.textContent?.trim();
    const href = l.href;
    if (text && !seen.has(href)) {
      seen.add(href);
      const parent = l.closest('.gallery-card, .cl-search-result, li');
      const price = parent?.querySelector('.priceinfo')?.textContent?.trim();
      const meta = parent?.querySelector('.meta')?.textContent?.trim();
      res.push({ text, href, price, meta });
    }
  }
  return res;
});
console.log("All unique listings:", JSON.stringify(allTrailers.filter(x => x.text.toLowerCase().includes('trailer') || x.text.toLowerCase().includes('tiny') || x.text.toLowerCase().includes('hauler') || x.text.toLowerCase().includes('camper')), null, 2));

