const tabId = 103795370;
const rentals = await browserjs(tabId, () => {
  const articles = Array.from(document.querySelectorAll('article, [data-test="property-card"]'));
  return articles.map(art => {
    const link = art.querySelector('a[data-test="property-card-link"], a.property-card-link, a');
    const price = art.querySelector('[data-test="property-card-price"], span[class*="PropertyCardHomePrice"], .property-card-price')?.textContent?.trim();
    const address = art.querySelector('address')?.textContent?.trim() || art.querySelector('[data-test="property-card-addr"]')?.textContent?.trim() || link?.textContent?.trim();
    const details = art.querySelector('ul')?.textContent?.trim();
    const href = link?.href;
    return { price, address, details, href };
  }).filter(x => x.price);
});

console.log("Found rentals under $700:", rentals.length);
console.log(rentals.slice(0, 10));

