  filterState: {
    sort: { value: "paymenta" },
    fr: { value: true },
    fsba: { value: false },
    fsbo: { value: false },
    nc: { value: false }
  },
  isListVisible: true,
  usersSearchTerm: "Los Angeles CA"
};

