  const cards = Array.from(document.querySelectorAll('article'));
  return {
    url: window.location.href,
    title: document.title,
    cardsCount: cards.length,
    listings: cards.map(c => ({
      price: c.querySelector('span[data-test="property-card-price"], [class*="PropertyCardHomePrice"], div[class*="price"]')?.textContent?.trim(),
      addr: c.querySelector('address')?.textContent?.trim(),
      link: c.querySelector('a[data-test="property-card-link"], a')?.href,
      info: c.querySelector('ul')?.textContent?.trim()
    })).filter(x => x.price)
  };
});

