const tabId = 103795370;
const roomListings = await browserjs(tabId, () => {
  const articles = Array.from(document.querySelectorAll('article'));
  return articles.map(a => {
    const price = a.querySelector('[data-test="property-card-price"], span[class*="PropertyCardHomePrice"], div[class*="price"]')?.textContent?.trim()
      || a.innerText.match(/\$[\d,]+(\/mo|\+)?/)?.[0];
    const link = a.querySelector('a[data-test="property-card-link"], a')?.href;
    const addr = a.querySelector('address')?.textContent?.trim() || a.querySelector('a')?.textContent?.trim();
    return {
      price,
      addr,
      link,
      text: a.innerText.slice(0, 200)
    };
  });
});

console.log(`Found ${roomListings.length} room listings on page 1:`);
console.log(JSON.stringify(roomListings.slice(0, 10), null, 2));

